// Format the WordPress taxonomy terms (brands) into a clean structure.
// WordPress REST API returns taxonomy terms with: id, name, slug, etc.

const inputItems = $input.all();

try {
  let brands = [];

  // n8n may split array responses into separate items
  const firstJson = inputItems[0]?.json;

  if (Array.isArray(firstJson)) {
    brands = firstJson;
  } else if (inputItems.length >= 1 && firstJson && firstJson.id) {
    // Items were split — each item is a brand term
    brands = inputItems.map(item => item.json);
  } else if (firstJson && firstJson.code) {
    // Error response (e.g., taxonomy not found)
    return [{
      json: {
        success: false,
        message: 'Could not fetch brands. Check that the brand taxonomy exists and is exposed to the REST API. Error: ' + (firstJson.message || firstJson.code),
        brands: []
      }
    }];
  }

  const cleanBrands = brands
    .filter(b => b && b.id)
    .map(b => ({
      id: b.id,
      name: b.name || ''
    }));

  return [{
    json: {
      success: true,
      brands: cleanBrands
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      message: 'Failed to fetch brands: ' + error.message,
      brands: []
    }
  }];
}
